{
  "name": "PC散热与灯效控制设备",
  "name_en": "PC Cooling and Lighting Control Device",
  "manufacturer": "",
  "description": "用于台式机或测试平台的硬件控制设备，可管理风扇或水泵转速、RGB灯光，以及部分机型的显示屏内容，并读取设备状态与标识信息。常见于一体式水冷、风扇集线器或机箱控制器。",
  "description_en": "A hardware control device used in desktop PCs or test benches to manage fan or pump speed, RGB lighting, and on some models integrated display content, while reporting device status and identification information. Common examples include AIO liquid coolers, fan hubs, and case controllers.",
  "tag_hints": [
    "PC cooling control",
    "fan and pump control",
    "RGB lighting",
    "AIO liquid cooler",
    "LCD status display",
    "hardware status monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接设备。",
      "description_en": "Connect to the device."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开设备连接。",
      "description_en": "Disconnect from the device."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化设备，使其进入可控制的工作状态。",
      "description_en": "Initialize the device so it enters a controllable operating state."
    },
    {
      "action_name": "auto-set_color",
      "description": "设置指定通道的灯光模式和颜色。",
      "description_en": "Set the lighting mode and colors for a specific channel."
    },
    {
      "action_name": "auto-set_fixed_speed",
      "description": "将指定通道设置为固定速度占空比。",
      "description_en": "Set a specific channel to a fixed speed duty."
    },
    {
      "action_name": "auto-set_screen",
      "description": "设置显示屏通道的显示模式和内容。",
      "description_en": "Set the display mode and content for a screen channel."
    },
    {
      "action_name": "auto-set_speed_profile",
      "description": "为指定通道设置速度占空比曲线。",
      "description_en": "Set a speed duty profile for a specific channel."
    },
    {
      "action_name": "auto-find_supported_devices",
      "description": "查找并绑定兼容设备。",
      "description_en": "Find and bind compatible devices."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取状态报告。",
      "description_en": "Get the status report."
    },
    {
      "action_name": "auto-description",
      "description": "获取设备的人类可读描述。",
      "description_en": "Get the human-readable device description."
    },
    {
      "action_name": "auto-vendor_id",
      "description": "获取厂商标识符。",
      "description_en": "Get the vendor identifier."
    },
    {
      "action_name": "auto-product_id",
      "description": "获取产品标识符。",
      "description_en": "Get the product identifier."
    },
    {
      "action_name": "auto-release_number",
      "description": "获取设备版本号。",
      "description_en": "Get the device release number."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号。",
      "description_en": "Get the serial number."
    },
    {
      "action_name": "auto-bus",
      "description": "获取设备所连接的总线信息。",
      "description_en": "Get the bus the device is connected to."
    },
    {
      "action_name": "auto-address",
      "description": "获取设备在总线上的地址。",
      "description_en": "Get the device address on the bus."
    },
    {
      "action_name": "auto-port",
      "description": "获取设备所连接的物理端口。",
      "description_en": "Get the physical port the device is connected to."
    },
    {
      "action_name": "auto-find_devices",
      "description": "查找设备。",
      "description_en": "Find devices."
    }
  ]
}

